mapper.select:
SELECT l.id AS like_id, u.id AS user_id, u.username, u.display_name, u.icon_image_key
FROM likes l
JOIN users u ON u.id = l.user_id
WHERE l.post_id = #{postId}

	AND l.id < #{beforeId}

ORDER BY l.id DESC
LIMIT #{limit}

SELECT l.id AS like_id, u.id AS user_id, u.username, u.display_name, u.icon_image_key
FROM comment_likes l
JOIN users u ON u.id = l.user_id
WHERE l.comment_id = #{commentId}

	AND l.id < #{beforeId}

ORDER BY l.id DESC
LIMIT #{limit}
